<template>
  <Teleport to="body">
    <dialog ref="dialog" class="audio-versions" aria-labelledby="audio-versions-title" @cancel.prevent="close">
      <header class="audio-versions-head">
        <div><h2 id="audio-versions-title">Summary audio</h2><p>{{ authenticated ? 'Listen, compare, and choose a recording.' : 'Enter the collection password to manage recordings.' }}</p></div>
        <button type="button" class="audio-versions-close" aria-label="Close audio versions" @click="close"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15" /></svg></button>
      </header>
      <form v-if="!authenticated" class="audio-versions-login" @submit.prevent="authenticate">
        <label for="audio-versions-password">Collection password</label>
        <input id="audio-versions-password" ref="password" v-model="password" type="password" autocomplete="current-password" :disabled="Boolean(busy)" required>
        <button type="submit" class="audio-versions-primary" :disabled="Boolean(busy) || !password">{{ busy ? 'Checking…' : 'Continue' }}</button>
      </form>
      <template v-else>
        <div v-if="versions.length" class="audio-versions-transport">
          <span>{{ previewVersion ? `Version ${previewVersion.number}` : 'Choose a recording' }}</span>
          <span class="audio-versions-time">{{ clock(currentTime) }} / {{ clock(duration) }}</span>
          <input type="range" min="0" :max="duration || 1" step="0.1" :value="currentTime" :disabled="!duration" :style="{ '--preview-progress': `${duration ? currentTime / duration * 100 : 0}%` }" aria-label="Preview playback position" :aria-valuetext="`${clock(currentTime)} of ${clock(duration)}`" @input="seek">
        </div>
        <ul class="audio-versions-list" aria-label="Summary recordings">
          <li v-for="version in versions" :key="version.id" :class="{ 'is-previewing': previewId === version.id, 'is-new': freshId === version.id }">
            <button type="button" class="audio-version-preview" :aria-label="`${previewId === version.id && playing ? 'Pause' : 'Play'} version ${version.number}`" :aria-pressed="previewId === version.id && playing" @click="playVersion(version)">
              <span class="audio-version-play" aria-hidden="true">
                <span v-if="previewId === version.id && previewLoading" class="audio-version-spinner"></span>
                <svg v-else-if="previewId === version.id && playing" viewBox="0 0 20 20"><path d="M7 5v10M13 5v10" /></svg>
                <svg v-else viewBox="0 0 20 20"><path class="audio-version-play-shape" d="m7 5 8 5-8 5Z" /></svg>
              </span>
              <span><strong>Version {{ version.number }}</strong><small>{{ versionDate(version) }}</small></span>
            </button>
            <span v-if="version.active" class="audio-version-in-use">In use</span>
            <button v-else type="button" class="audio-version-use" :disabled="Boolean(busy)" :aria-label="`Use version ${version.number}`" @click="useVersion(version)">{{ busy === `use-${version.id}` ? 'Saving…' : 'Use this' }}</button>
            <button type="button" class="audio-version-delete" :disabled="Boolean(busy) || version.active" :aria-label="`Delete version ${version.number}`" :title="version.active ? 'Choose another version before deleting this one.' : `Delete version ${version.number}`" @click="deleteId = version.id">
              <svg viewBox="0 0 20 20" aria-hidden="true"><path d="M4 5.5h12M8 3h4l1 2.5H7L8 3ZM6 5.5l.7 11h6.6l.7-11M8.5 8v6M11.5 8v6" /></svg>
            </button>
            <div v-if="deleteId === version.id" class="audio-version-confirm">
              <span>Delete version {{ version.number }}?</span>
              <button type="button" :disabled="Boolean(busy)" @click="deleteId = ''">Keep</button>
              <button type="button" class="audio-version-delete-confirm" :disabled="Boolean(busy)" @click="deleteVersion(version)">{{ busy === `delete-${version.id}` ? 'Deleting…' : 'Delete' }}</button>
            </div>
          </li>
        </ul>
        <p v-if="!versions.length && !busy" class="audio-versions-empty">No recordings yet. Generate one to listen.</p>
        <footer class="audio-versions-foot">
          <p>{{ busy === 'generate' ? 'Recording a new version…' : 'New recordings stay here until you choose one.' }}</p>
          <button type="button" class="audio-versions-primary" :disabled="Boolean(busy)" @click="generate">{{ busy === 'generate' ? 'Generating…' : 'Generate new' }}</button>
        </footer>
      </template>
      <p v-if="error || previewError" class="audio-versions-error" role="alert">{{ error || previewError }}</p>
      <p v-if="notice || busy === 'load'" class="audio-versions-notice" role="status">{{ busy === 'load' ? 'Loading recordings…' : notice }}</p>
      <audio ref="preview" :src="previewSrc || undefined" preload="none" @loadedmetadata="loaded" @timeupdate="updateTime" @durationchange="updateTime" @play="onPlay" @pause="onPause" @ended="onPause" @error="onPlaybackError" />
    </dialog>
  </Teleport>
</template>

<script>
import { hasSharedViewsAdminSession, clearSharedViewsAdminSession, loginSharedViewsAdmin,
  listManagedViewAudio, regenerateManagedViewAudio, selectManagedViewAudio, deleteManagedViewAudio } from '../../utils/viewShareSite';
import { initDialogBackdrop } from '../../utils/dialogBackdrop';

export default {
  name: 'ViewAudioVersions',
  props: { shareId: { type: String, required: true } },
  emits: ['close', 'audio-selected'],
  data: () => ({ authenticated: false, password: '', busy: '', error: '', notice: '', versions: [], currentAudio: null,
    previewId: '', previewSrc: '', previewLoading: false, previewError: '', playing: false, currentTime: 0, duration: 0,
    freshId: '', deleteId: '' }),
  computed: { previewVersion() { return this.versions.find(version => version.id === this.previewId); } },
  mounted() {
    this._abort = new AbortController();
    this.$refs.dialog.showModal();
    this._stopBackdrop = initDialogBackdrop(this.$refs.dialog, () => this.close());
    this._otherAudio = event => { if (event.detail !== this) this.$refs.preview?.pause(); };
    window.addEventListener('view-summary-play', this._otherAudio);
    if (hasSharedViewsAdminSession()) this.load();
    else this.$refs.password?.focus();
  },
  beforeUnmount() {
    this._closed = true;
    this._abort?.abort();
    this._stopBackdrop?.();
    this.$refs.preview?.pause();
    this.$refs.dialog?.close();
    window.removeEventListener('view-summary-play', this._otherAudio);
  },
  methods: {
    close() { this._closed = true; this._abort?.abort(); this.$emit('close'); },
    async action(name, work) {
      if (this.busy) return;
      this.busy = name; this.error = ''; this.notice = '';
      try { await work(this._abort.signal); }
      catch (error) {
        if (this._closed) return;
        const message = error?.message;
        if (['forbidden', 'invalid_credentials'].includes(message)) {
          clearSharedViewsAdminSession(); this.resetPreview(); this.versions = []; this.currentAudio = null; this.authenticated = false; this.password = '';
          this.$nextTick(() => this.$refs.password?.focus());
        }
        this.error = message === 'invalid_credentials' ? 'That password did not work.'
          : message === 'forbidden' ? 'Enter the collection password to continue.'
            : message === 'too_many_attempts' ? 'Please wait a minute before trying again.'
              : message === 'version_in_use' ? 'Choose another recording before deleting this one.'
                : message === 'conflict' ? 'The selected recording changed. Review the list and try again.'
                  : 'The recording could not be updated. Please try again.';
        if (['conflict', 'version_in_use', 'version_not_found', 'version_deleted'].includes(message)) {
          try { this.apply(await listManagedViewAudio(this.shareId, this._abort.signal)); } catch { /* Keep the original actionable error. */ }
        }
      } finally { if (!this._closed) this.busy = ''; }
    },
    apply(data) {
      if (this._closed) return;
      this.authenticated = true; this.password = '';
      this.versions = data.versions; this.currentAudio = data.current_audio;
      if (this.previewId && !this.versions.some(version => version.id === this.previewId)) this.resetPreview();
    },
    load() { return this.action('load', async signal => this.apply(await listManagedViewAudio(this.shareId, signal))); },
    authenticate() {
      if (!this.password) return;
      return this.action('auth', async signal => {
        await loginSharedViewsAdmin(this.password, signal);
        this.apply(await listManagedViewAudio(this.shareId, signal));
      });
    },
    generate() {
      return this.action('generate', async signal => {
        this._generationId ||= crypto.randomUUID();
        const controller = new AbortController();
        const cancel = () => controller.abort();
        signal.addEventListener('abort', cancel, { once: true });
        const timeout = setTimeout(cancel, 120000);
        let audio;
        try { audio = await regenerateManagedViewAudio(this.shareId, this._generationId, controller.signal); }
        catch (error) {
          if (['unavailable', 'audio_unavailable', 'conflict', 'invalid_summary', 'not_found', 'version_deleted'].includes(error?.message)) this._generationId = null;
          throw error;
        } finally { clearTimeout(timeout); signal.removeEventListener('abort', cancel); }
        this._generationId = null;
        this.apply(await listManagedViewAudio(this.shareId, signal));
        if (this._closed) return;
        this.freshId = this.versions.find(version => version.audio.src === audio.src)?.id || '';
        this.notice = 'New recording ready to compare.';
      });
    },
    useVersion(version) {
      return this.action(`use-${version.id}`, async signal => {
        const data = await selectManagedViewAudio(this.shareId, version.id, this.currentAudio?.src || '', signal);
        if (this._closed) return;
        this.apply(data); this.$emit('audio-selected', data.current_audio);
        this.notice = `Version ${version.number} is now in use.`;
      });
    },
    deleteVersion(version) {
      return this.action(`delete-${version.id}`, async signal => {
        this.apply(await deleteManagedViewAudio(this.shareId, version.id, signal));
        if (this._closed) return;
        this.deleteId = ''; this.notice = `Version ${version.number} deleted.`;
      });
    },
    async playVersion(version) {
      const audio = this.$refs.preview;
      if (this.previewId === version.id && (this.playing || this.previewLoading)) { this._playId = (this._playId || 0) + 1; audio.pause(); this.previewLoading = false; return; }
      this.previewError = '';
      const playId = this._playId = (this._playId || 0) + 1;
      if (this.previewId !== version.id) {
        this._seekAfterLoad = this.currentTime;
        audio.pause(); this.previewId = version.id; this.previewSrc = version.audio.src;
        this.previewLoading = true; this.duration = 0;
        await this.$nextTick();
      } else if (audio.ended) audio.currentTime = 0;
      if (this._closed || this._playId !== playId) return;
      this.previewLoading = true;
      try { await audio.play(); }
      catch (error) {
        if (this._closed || this._playId !== playId || error.name === 'AbortError') return;
        this.previewError = 'Tap play to listen to this recording.'; this.previewLoading = false;
      }
    },
    loaded() {
      const audio = this.$refs.preview;
      if (Number.isFinite(this._seekAfterLoad) && Number.isFinite(audio.duration)) {
        audio.currentTime = this._seekAfterLoad < audio.duration ? this._seekAfterLoad : 0;
        this._seekAfterLoad = null;
      }
      this.updateTime();
    },
    onPlay() {
      this.playing = true; this.previewLoading = false;
      window.dispatchEvent(new CustomEvent('view-summary-play', { detail: this }));
    },
    onPause() { this.playing = false; window.dispatchEvent(new CustomEvent('view-summary-pause', { detail: this })); },
    onPlaybackError() { if (this.previewSrc) { this.previewLoading = false; this.previewError = 'Audio is unavailable. Try another recording.'; } },
    resetPreview() { this._playId = (this._playId || 0) + 1; this.$refs.preview?.pause(); this.previewId = ''; this.previewSrc = ''; this.currentTime = 0; this.duration = 0; this.previewLoading = false; this.previewError = ''; this.playing = false; this._seekAfterLoad = null; },
    updateTime() { const audio = this.$refs.preview; this.currentTime = audio?.currentTime || 0; this.duration = Number.isFinite(audio?.duration) ? audio.duration : 0; },
    seek(event) { this.$refs.preview.currentTime = Number(event.target.value); this.updateTime(); },
    clock(seconds) { const n = Math.floor(seconds || 0); return `${Math.floor(n / 60)}:${String(n % 60).padStart(2, '0')}`; },
    versionDate(version) { return version.created_at ? new Date(version.created_at).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }) : 'Existing recording'; },
  },
};
</script>

