.audio-versions-error, .audio-versions-notice, .audio-versions-empty { margin: 14px 0 0; color: var(--site-text-secondary, #666); font: inherit; }
.audio-versions-empty { margin-bottom: 20px; }
.audio-versions-error { color: var(--site-text-primary, #333); }
.audio-version-spinner { width: 12px; height: 12px; border: 1px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: audio-version-spin 600ms linear infinite; }
@keyframes audio-version-spin { to { transform: rotate(360deg); } }
:global(body.dark-mode .audio-versions) { --site-bg: #242425; --site-text-primary: #e6e2dc; --site-text-secondary: #b4b1ad; }
@media (hover: hover) and (pointer: fine) { .audio-versions button:hover:not(:disabled) { background-color: color-mix(in srgb, currentColor 7%, transparent); } .audio-versions .audio-versions-primary:hover:not(:disabled) { background-color: color-mix(in srgb, var(--site-text-primary, #333) 85%, var(--site-bg, #fff)); } }
@media (max-width: 480px) { .audio-versions { padding: 20px 16px; } .audio-versions-foot { gap: 12px; } .audio-versions-foot p { font-size: 11px; } }
@media (prefers-reduced-motion: reduce) { .audio-versions button { transition: none; } .audio-version-spinner { animation: none; } }
</style>
