.home-page-preview-heading { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 12px; font: .62rem/1.4 'Quattrocento Sans',sans-serif; letter-spacing: .12em; text-transform: uppercase; color: #777; border-bottom: 1px solid rgba(80,80,80,.12); }
.home-page-preview-heading a { display: inline-flex; align-items: center; gap: 6px; color: inherit; text-decoration: none; padding: 2px 0; }
.home-page-preview-heading svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.2; transition: transform 200ms ease; }
.home-page-preview-heading a:hover { color: #111; }
.home-page-preview-heading a:hover svg { transform: translateX(3px); }
.home-page-preview iframe { display: block; width: 100%; height: min(340px,calc(100svh - 100px)); border: 0; background: #fff; }
:global(body.dark-mode .home-page-preview) { background: #2c2c2e; border-color: rgba(255,255,255,.14); }
:global(body.dark-mode .home-page-preview-heading) { color: #aaa; border-color: rgba(255,255,255,.1); }
:global(body.dark-mode .home-page-preview-heading a:hover) { color: #fff; }
:global(body.dark-mode .home-page-preview iframe) { background: #1c1c1e; }
.home-page-preview-enter-active,.home-page-preview-leave-active { transition: opacity 180ms ease,transform 200ms cubic-bezier(.23,1,.32,1); }
.home-page-preview-enter-from,.home-page-preview-leave-to { opacity: 0; transform: translateY(6px); }
@media (prefers-reduced-motion: reduce) { .home-page-preview-enter-active,.home-page-preview-leave-active,.home-page-preview-heading svg { transition: none; } }
</style>
