<template>
  <section class="review-architecture" :aria-label="strategy ? architecture.title : 'How the two reading strategies gather evidence'">
    <div v-if="!strategy" class="review-architecture-switch" role="group" aria-label="Reading strategy">
      <button v-for="(item, key) in architectures" :key="key" type="button" :aria-pressed="mode === key" @click="selectMode(key)">{{ item.title }}</button>
    </div>
    <svg class="review-architecture-canvas" :viewBox="compact ? '0 0 340 420' : '0 0 900 375'" role="img" :aria-label="frame.caption">
      <g :opacity="1 - smooth(frame.merging)">
        <g v-if="searching" :transform="`translate(${layout.guide.x} ${layout.guide.y})`">
          <text class="review-svg-heading" x="0" y="0">Risk guidance</text>
          <g v-for="(label, index) in guidanceLabels" :key="label" :opacity="guidanceIndex === index ? 1 : .28" :transform="`translate(0 ${compact ? 23 : 50 + index * 49})`">
            <template v-if="!compact || guidanceIndex === index">
              <circle cx="4" cy="-5" r="3" fill="currentColor" />
              <text class="review-svg-body" x="18" y="0">{{ label }}</text>
            </template>
          </g>
        </g>
        <g v-if="searching" :transform="queryTransform" :opacity="queryOpacity">
          <circle cx="7" cy="-6" r="6" class="review-svg-stroke" />
          <path d="m12 -1 5 5" class="review-svg-stroke" />
          <text class="review-svg-small" x="27" y="0">{{ frame.local >= 3300 ? 'Check evidence' : `Search ${frame.round + 1}` }}</text>
        </g>
        <g :transform="`translate(${layout.paper.x} ${layout.paper.y})`">
          <rect class="review-paper-shadow" x="4" y="6" :width="layout.paper.w" :height="layout.paper.h" rx="3" />
          <rect class="review-paper" x="0" y="0" :width="layout.paper.w" :height="layout.paper.h" rx="3" />
          <g :opacity="pageOpacity">
            <text class="review-svg-heading" x="18" y="32">{{ searching ? 'Result' : 'Report' }}</text>
            <text class="review-svg-small review-svg-muted" x="18" y="55">{{ searching ? 'Source passage' : `Page 0${frame.round + 1}` }}</text>
            <rect v-for="line in 5" :key="line" class="review-text-line" x="18" :y="77 + (line - 1) * 17" :width="layout.paper.w - (line === 5 ? 59 : 36)" height="3" rx="1.5" />
            <rect v-for="passage in (searching ? 1 : 2)" :key="`passage-${passage}`" class="review-passage" x="12" :y="searching ? 102 : 84 + (passage - 1) * 34" :width="layout.paper.w - 24" :height="searching ? 41 : 27" rx="2" :opacity="passageOpacity(passage - 1)" />
            <text class="review-svg-small review-svg-muted" x="18" :y="layout.paper.h - 19">{{ searching ? 'Page reference' : 'Read page by page' }}</text>
          </g>
          <g :opacity="scanOpacity" :transform="`translate(0 ${scanY})`">
            <rect class="review-scan" x="12" y="0" :width="layout.paper.w - 24" height="15" rx="2" />
            <circle cx="6" cy="7" r="2" fill="currentColor" />
          </g>
        </g>
        <text v-if="!searching" class="review-svg-heading" :x="layout.records.x" :y="layout.records.y - 21" :opacity="interval(elapsed, 1000, 1500)">Evidence records</text>
      </g>
      <g v-for="record in frame.records" :key="record.index" :transform="recordTransform(record)" :opacity="recordOpacity(record)">
        <rect class="review-paper-shadow" x="2" y="3" :width="layout.records.w" :height="layout.records.h" rx="3" />
        <rect class="review-paper" :width="layout.records.w" :height="layout.records.h" rx="3" />
        <rect x="0" y="12" width="2" :height="layout.records.h - 24" fill="currentColor" opacity=".55" />
        <text class="review-svg-record" x="14" :y="compact && !searching ? 19 : 25">{{ compact && searching && record.index === 0 ? 'Observation' : record.label }}</text>
        <text class="review-svg-small review-svg-muted" x="14" :y="compact && !searching ? 35 : 46">{{ searching ? 'Source' : 'Page' }} {{ String(record.source + 1).padStart(2, '0') }}</text>
      </g>
      <g :transform="assessmentTransform" :opacity="assessmentOpacity">
        <rect class="review-paper-shadow" x="4" y="6" :width="layout.result.w" height="264" rx="3" />
        <rect class="review-paper" :width="layout.result.w" height="264" rx="3" />
        <text class="review-svg-result" x="25" y="43">Risk assessment</text>
        <g :opacity="interval(frame.merging, .48, .76)">
          <text class="review-svg-body" x="25" y="81">Finding</text>
          <rect class="review-text-line" x="25" y="96" :width="layout.result.w - 72" height="4" rx="2" />
          <text class="review-svg-body" x="25" y="136">Reasoning</text>
          <rect class="review-text-line" x="25" y="151" :width="layout.result.w - 50" height="4" rx="2" />
          <rect class="review-text-line" x="25" y="165" :width="layout.result.w - 96" height="4" rx="2" />
        </g>
        <g :opacity="interval(frame.merging, .7, 1)">
          <text class="review-svg-small review-svg-muted" x="25" y="208">Supporting sources</text>
          <g v-for="source in 3" :key="source" :transform="`translate(${25 + (source - 1) * 65} 221)`">
            <rect class="review-passage" width="51" height="24" rx="2" />
            <text class="review-svg-small" x="25.5" y="17" text-anchor="middle">0{{ source }}</text>
          </g>
        </g>
      </g>
    </svg>
    <p class="review-architecture-caption" :aria-live="playing ? 'off' : 'polite'" aria-atomic="true">{{ frame.caption }}</p>
    <div class="review-architecture-controls">
      <button type="button" class="review-play" :aria-label="controlLabel" @click="togglePlayback">
        <svg v-if="frame.finished" viewBox="0 0 20 20" aria-hidden="true"><path d="M4 7a6 6 0 1 1 0 6M4 2v5h5" /></svg>
        <svg v-else-if="reducedMotion" viewBox="0 0 20 20" aria-hidden="true"><path d="m7 4 6 6-6 6" /></svg>
        <svg v-else-if="playing" viewBox="0 0 20 20" aria-hidden="true"><path d="M7 4v12M13 4v12" /></svg>
        <svg v-else viewBox="0 0 20 20" aria-hidden="true"><path d="m7 4 8 6-8 6z" /></svg>
      </button>
      <input type="range" min="0" :max="architecture.duration" step="50" :value="elapsed" aria-label="Animation progress" :aria-valuetext="frame.caption" @input="seek" />
    </div>
  </section>
</template>
<script>
import { documentReviewArchitectures, documentReviewFrame, intervalProgress, smoothProgress } from '../../data/documentReview';

export default {
  name: 'DocumentReviewArchitecture',
  props: {
    strategy: { type: String, default: '', validator: value => ['', 'coverage', 'retrieval'].includes(value) },
  },
  data() { return { mode: this.strategy || 'coverage', architectures: documentReviewArchitectures, elapsed: 0, compact: false, playing: true, visible: false, active: true, reducedMotion: false }; },
  computed: {
    architecture() { return this.architectures[this.mode]; },
    frame() { return documentReviewFrame(this.mode, this.elapsed); },
    searching() { return this.mode === 'retrieval'; },
    guidanceLabels() { return ['Evidence needed', 'Where to look', 'Decision rules']; },
    guidanceIndex() { return this.frame.guidanceIndex; },
    layout() {
      if (this.compact) return {
        guide: { x: 18, y: 25 },
        paper: { x: 12, y: this.searching ? 140 : 76, w: 135, h: 192 },
        records: { x: 177, y: this.searching ? 132 : 59, w: 151, h: this.searching ? 62 : 45, gap: this.searching ? 78 : 51, columns: 1 },
        result: { x: 28, y: 68, w: 284 },
      };
      return {
        guide: { x: 47, y: 90 },
        paper: { x: this.searching ? 642 : 154, y: 72, w: 184, h: 232 },
        records: { x: this.searching ? 343 : 451, y: 83, w: this.searching ? 250 : 174, h: 66, gap: 83, columns: this.searching ? 1 : 2 },
        result: { x: 283, y: 50, w: 334 },
      };
    },
    pageOpacity() {
      if (this.frame.settling) return 1;
      const local = this.frame.local;
      const entrance = this.frame.round === 0 ? 1 : this.smooth(this.interval(local, 0, 230));
      const exit = this.frame.round < 2 ? 1 - this.smooth(this.interval(local, this.architecture.cycle - 220, this.architecture.cycle)) : 1;
      return entrance * exit;
    },
    scanOpacity() { return this.frame.settling ? 0 : this.interval(this.frame.local, 180, 450) * (1 - this.interval(this.frame.local, 1750, 2100)); },
    scanY() { return 72 + this.smooth(this.interval(this.frame.local, 250, 1900)) * 61; },
    queryOpacity() { return this.frame.settling ? 0 : this.interval(this.frame.local, 120, 380) * (this.frame.local < 3300 ? 1 - this.interval(this.frame.local, 1350, 1600) : this.interval(this.frame.local, 3300, 3500) * (1 - this.interval(this.frame.local, 3920, 4150))); },
    queryTransform() {
      const returning = this.frame.local >= 3300;
      const travel = returning ? 1 - this.smooth(this.interval(this.frame.local, 3300, 4100)) : this.smooth(this.interval(this.frame.local, 120, 1450));
      return `translate(${this.compact ? 63 + travel * 54 : 333 + travel * 182} ${this.compact ? 105 : 47})`;
    },
    assessmentOpacity() { return this.smooth(this.interval(this.frame.merging, .3, .65)); },
    assessmentTransform() { return `translate(${this.layout.result.x} ${this.layout.result.y + 8 * (1 - this.assessmentOpacity)})`; },
    controlLabel() { return this.frame.finished ? 'Replay animation' : this.reducedMotion ? 'Next stage' : this.playing ? 'Pause animation' : 'Play animation'; },
  },
  mounted() {
    this._motionPreference = window.matchMedia('(prefers-reduced-motion: reduce)');
    this.onMotionPreference();
    this._motionPreference.addEventListener('change', this.onMotionPreference);
    this._sizeObserver = new ResizeObserver(([entry]) => { this.compact = entry.contentRect.width < 570; });
    this._sizeObserver.observe(this.$el);
    this._visibilityObserver = new IntersectionObserver(([entry]) => { this.visible = entry.isIntersecting; this.syncPlayback(); }, { threshold: .2 });
    this._visibilityObserver.observe(this.$el);
    document.addEventListener('visibilitychange', this.syncPlayback);
  },
  activated() { this.active = true; this.syncPlayback(); },
  deactivated() { this.active = false; this.stopClock(); },
  beforeUnmount() {
    this.stopClock();
    this._sizeObserver?.disconnect();
    this._visibilityObserver?.disconnect();
    this._motionPreference?.removeEventListener('change', this.onMotionPreference);
    document.removeEventListener('visibilitychange', this.syncPlayback);
  },
  methods: {
    interval: intervalProgress,
    smooth: smoothProgress,
    passageOpacity(index) {
      const start = this.searching ? 1600 : 700 + index * 1000;
      return this.interval(this.frame.local, start, start + 350) * this.pageOpacity;
    },
    recordTransform(record) {
      const p = this.smooth(record.progress);
      const stagger = record.index * (this.searching ? .12 : .045);
      const merge = this.smooth(this.interval(this.frame.merging, stagger, .7 + stagger));
      const { paper, records, result } = this.layout;
      const destinationX = records.x + (record.index % records.columns) * (records.w + 18);
      const destinationY = records.y + Math.floor(record.index / records.columns) * records.gap;
      const sourceY = paper.y + (this.searching ? 102 : 84 + record.observation * 34);
      const x = paper.x + 12 + (destinationX - paper.x - 12) * p;
      const y = sourceY + (destinationY - sourceY) * p;
      return `translate(${x + (result.x + 25 + record.source * 65 - x) * merge} ${y + (result.y + 221 - y) * merge}) scale(${.92 + .08 * p - merge * .18})`;
    },
    recordOpacity(record) {
      const stagger = record.index * (this.searching ? .12 : .045);
      return this.interval(record.progress, 0, .24) * (1 - this.interval(this.frame.merging, .32 + stagger, .7 + stagger));
    },
    selectMode(mode) {
      if (this.mode === mode) return;
      this.stopClock();
      this.mode = mode;
      this.elapsed = 0;
      this.playing = !this.reducedMotion;
      this.syncPlayback();
    },
    onMotionPreference() { this.reducedMotion = this._motionPreference.matches; if (this.reducedMotion) this.playing = false; this.syncPlayback(); },
    stopClock() { if (this._raf) cancelAnimationFrame(this._raf); this._raf = null; this._previousTime = null; },
    syncPlayback() {
      this.stopClock();
      if (this.playing && this.visible && this.active && !document.hidden && !this.reducedMotion && !this.frame.finished) this._raf = requestAnimationFrame(this.tick);
    },
    tick(timestamp) {
      if (this._previousTime != null) this.elapsed = Math.min(this.architecture.duration, this.elapsed + timestamp - this._previousTime);
      this._previousTime = timestamp;
      if (this.frame.finished) { this.playing = false; this.stopClock(); }
      else this._raf = requestAnimationFrame(this.tick);
    },
    togglePlayback() {
      if (this.reducedMotion) {
        const steps = [...this.architecture.steps, this.architecture.duration];
        this.elapsed = steps.find(time => time > this.elapsed) ?? 0;
        return;
      }
      if (this.frame.finished) { this.elapsed = 0; this.playing = true; }
      else this.playing = !this.playing;
      this.syncPlayback();
    },
    seek(event) { this.playing = false; this.stopClock(); this.elapsed = Number(event.target.value); },
  },
};
</script>
