<template>
  <section class="mono-conversation" :class="{'is-open':open}" aria-label="Ask about Henry" @keydown.esc.stop="close">

    <Transition name="mono-answer-presence">
      <div v-if="open" class="mono-answer-panel">
        <button class="mono-answer-close" aria-label="Close answer" @click="close"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 5 14 14M19 5 5 19"/></svg></button>
        <div ref="answerScroll" class="mono-answer-scroll" role="region" aria-label="Answer and sources" tabindex="0" :aria-busy="busy" @click.capture="rememberNavigation">
          <Transition name="mono-answer-turn" mode="out-in">
            <div :key="turn">
              <h2 class="mono-submitted-question">{{submitted}}</h2>
              <div v-if="busy&&!answerText" class="mono-answer-thinking" role="status"><span aria-hidden="true"></span><p>Finding the relevant parts of the site</p></div>
              <div v-if="answerText" class="mono-answer-copy" v-html="answerHtml"></div>
              <p v-if="error" class="mono-answer-error" role="alert">{{error}}</p>
              <AskAnswerAudio v-if="answerText&&!busy" :text="answerText"/>
              <AskActions v-if="actions.length&&answerText&&!busy" :actions="actions" surface="home"/>
              <ViewComposeProgress v-if="viewBusy" surface="home" :started-at="viewStart"/>
              <p v-if="viewError&&!viewBusy" class="mono-answer-error" role="alert">{{viewError}}</p>
              <AskViewOffer v-if="!viewBusy&&(routing==='offer'||existingView)&&answerText&&!busy&&!error" :ready="existingView" :title="offer.title" :description="offer.description" @explore="createView"/>
              <div v-if="followUps.length&&!busy&&answerText" class="mono-answer-followups"><span>Keep exploring</span><button v-for="followUp in followUps" :key="followUp" :disabled="locked" @click="run(followUp)"><span>{{followUp}}</span></button></div>
              <div v-if="citations.length&&!busy" class="mono-answer-sources"><span>Sources</span><a v-for="source in citations" :key="source.route+'#'+source.anchor" :href="sourceHref(source)" @click.prevent="goSource(source)"><span class="mono-source-surface"><span class="mono-source-details"><small>{{source.page}}</small><span>{{source.title}}</span></span><ArrowUpRightIcon/></span></a></div>
            </div>
          </Transition>
        </div>
      </div>
    </Transition>
    <form class="mono-ask" @submit.prevent="submit" @click.self="$refs.input?.focus()">
      <input ref="input" v-model="question" aria-label="Ask a question about Henry" :placeholder="open?'Ask another question...':'Ask me a question...'" autocomplete="off" :disabled="locked" @focus="$emit('editing')" @compositionstart="composing=true" @compositionend="composing=false"/>
      <button type="submit" :disabled="!question.trim()||locked" :aria-label="busy?'Finding an answer':'Submit question'"><svg class="mono-ask-arrow" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M3 11.25h14V7l5 5-5 5v-4.25H3Z"/></svg></button>
    </form>
  </section>
</template>
<script>
import ArrowUpRightIcon from '../../components/ui/ArrowUpRightIcon.vue';
import AskAnswerAudio from '../../components/ui/AskAnswerAudio.vue';
import AskActions from '../../components/ui/AskActions.vue';
import AskViewOffer from '../../components/ui/AskViewOffer.vue';
import ViewComposeProgress from '../../components/view/ViewComposeProgress.vue';
import {askConfigured,askStream,askErrorMessage} from '../../utils/askSite';
import {allAskContexts,askAnswerFollowUps,askViewOffer,askViewRouting,groundAskFollowUps,looksLikeViewBuildRequest,askResponseIsComplete,citedSourcesFromAnswer,cleanAskAnswer,cleanAskContextText,diversifyAskWritingContexts,sourceDisplayTitle} from '../../utils/askRetrieval';
import {askActionsForDisplay,renderAskAnswerLinks} from '../../utils/askActions';
import {newAskContext} from '../../utils/askTelemetry';
import {addAskTurn,askSourceIdsInRecent,loadAskSession,matchingAskView} from '../../utils/askSession';
import {isViewComposing,viewComposeState} from '../../utils/viewSite';
import {sourceRouteTarget} from '../../utils/viewSourceTarget';
import {prepareAskSourceReturn} from '../../utils/askReturn';
// Keep the homepage answer available across source navigation.
let savedHomeAnswer=null;
export function hasSavedHomeAnswer(){return Boolean(savedHomeAnswer?.open);}
export default {
  components:{ArrowUpRightIcon,AskAnswerAudio,AskActions,AskViewOffer,ViewComposeProgress},
  emits:['engaged','editing'],
  data(){return{open:false,question:'',submitted:'',answer:'',sources:[],busy:false,error:'',turn:0,composing:false,routing:'none',grounded:null,viewError:'',session:loadAskSession(),...(savedHomeAnswer||{})};},
  computed:{
    locked(){return this.busy||isViewComposing();},
    answerText(){return cleanAskAnswer(this.answer);},
    answerHtml(){return renderAskAnswerLinks(this.answerText);},
    actions(){return askActionsForDisplay(this.answer,this.routing).filter(entry=>!(entry.type==='action'&&entry.action==='ask'));},
    citations(){const seen=new Set();return citedSourcesFromAnswer(this.answer,this.sources).filter(s=>{const key=s.route+'#'+(s.anchor||'');if(seen.has(key))return false;seen.add(key);return true;}).map(s=>({...s,title:sourceDisplayTitle(s)}));},
    followUps(){return this.grounded??askAnswerFollowUps(this.answer).slice(0,3);},
    offer(){return askViewOffer(this.answer);},
    existingView(){return !!matchingAskView(this.submitted,this.session);},
    viewBusy(){return viewComposeState.active&&viewComposeState.surface==='home'&&viewComposeState.label===this.submitted;},
    viewStart(){return viewComposeState.startedAt;},
  },
  mounted(){this.sequence=0;this.$emit('engaged',this.open);this.onSession=e=>{this.session=e.detail;};this.onViewError=e=>{this.viewError=String(e.detail?.message||'Please try again.');};addEventListener('ask-session-updated',this.onSession);addEventListener('home-view-error',this.onViewError);if(savedHomeAnswer)this.$nextTick(()=>{if(this.$refs.answerScroll)this.$refs.answerScroll.scrollTop=savedHomeAnswer.answerTop||0;});},
  beforeUnmount(){this.save();this.sequence++;removeEventListener('ask-session-updated',this.onSession);removeEventListener('home-view-error',this.onViewError);},
  methods:{
    submit(){if(this.composing||this.locked||!this.question.trim())return;this.run(this.question.trim());},
    close(){this.sequence++;this.busy=false;this.open=false;this.question='';savedHomeAnswer=null;this.$emit('engaged',false);this.$nextTick(()=>this.$refs.input?.focus({preventScroll:true}));},
    save(){if(!this.open||this.busy)return;savedHomeAnswer={open:this.open,question:this.question,submitted:this.submitted,answer:this.answer,sources:this.sources,error:this.error,turn:this.turn,routing:this.routing,grounded:this.grounded,answerTop:this.$refs.answerScroll?.scrollTop||0};},
    async run(question){
      if(this.locked)return;
      const sequence=++this.sequence;
      this.open=true;this.$emit('engaged',true);this.submitted=question;this.question='';this.answer='';this.sources=[];this.error='';this.viewError='';this.routing='none';this.grounded=null;this.turn++;this.$refs.input?.blur();
      if(looksLikeViewBuildRequest(question)){this.createView();return;}
      this.busy=true;const telemetry=newAskContext('home');
      await this.$nextTick();if(this.$refs.answerScroll)this.$refs.answerScroll.scrollTop=0;
      try{
        if(!askConfigured())throw new Error('ask unavailable');
        const recent=askSourceIdsInRecent(loadAskSession(),18);
        const contexts=diversifyAskWritingContexts(await allAskContexts(question),question,telemetry.event_id,recent);
        if(sequence!==this.sequence)return;
        this.sources=contexts;
        const payload=contexts.map(context=>({page:context.page,title:sourceDisplayTitle(context),text:cleanAskContextText(context.body),source_id:context.source_id||context.chunk_id||String(context.id||'')}));
        let answer='';
        for await(const token of askStream(question,payload,{meta:{event_id:telemetry.event_id,session_id:telemetry.session_id,turn_index:telemetry.turn_index,surface:telemetry.surface,recent_source_ids:recent}})){
          if(sequence!==this.sequence)return;
          answer+=token;this.answer=answer;
        }
        if(!askResponseIsComplete(answer))throw new Error('incomplete ask response');
        if(sequence!==this.sequence)return;
        this.routing=askViewRouting(answer);
        addAskTurn(addAskTurn(loadAskSession(),{role:'user',text:question,source_ids:[]}),{role:'assistant',text:answer,source_ids:citedSourcesFromAnswer(answer,contexts).map(s=>s.source_id).filter(Boolean)});
        if(this.routing==='build')this.createView();
        groundAskFollowUps(askAnswerFollowUps(answer).slice(0,3)).then(questions=>{if(sequence===this.sequence)this.grounded=questions;}).catch(()=>{});
      }catch{if(sequence===this.sequence){this.answer='';this.sources=[];this.error=askErrorMessage();}}
      finally{if(sequence===this.sequence){this.busy=false;this.save();}}
    },
    sourceHref(source){const destination=sourceRouteTarget(source.route,source.anchor);return destination?.href||`#${source.route}${source.anchor?'#'+source.anchor:''}`;},
    rememberNavigation(event){if(event.target.closest('.ask-inline-link,.ask-action[data-ask-navigate]'))this.rememberReturn();},
    rememberReturn(){this.save();prepareAskSourceReturn({route:this.$route.fullPath,label:'Ask',scrollY:window.scrollY,askReturn:{surface:'home'}});},
    goSource(source){if(!source?.route)return;const destination=sourceRouteTarget(source.route,source.anchor);if(destination?.href){window.open(destination.href,'_blank','noopener');return;}this.rememberReturn();this.$router.push({path:source.route,hash:source.anchor?'#'+source.anchor:''}).catch(()=>{});},
    createView(){if(!this.submitted||isViewComposing())return;this.save();this.viewError='';if(matchingAskView(this.submitted,loadAskSession())){this.$router.push('/view').catch(()=>{});return;}window.dispatchEvent(new CustomEvent('open-site-view',{detail:{question:this.submitted,compose:true,askOfferConfirmed:true,surface:'home',returnContext:{pageY:window.scrollY,answerTop:this.$refs.answerScroll?.scrollTop||0}}}));},
  },
};
</script>
